    part def ControlSystem {
        part controller: Controller;
        part actuator: Actuator;
        part sensor: Sensor;

// 内部连接
        connect controller.cmdIn to externalCmd;
        connect controller.dataIO to sensor.dataOut;
        connect actuator.cmdIn to controller.cmdIn;

// 外部端口
        port externalCmd: CommandPort;
